/* ÇEVİRİ nl · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("nl","olay",{
"OLAYLAR:1299-01:0":{"b": ["Stichting van het Osmaanse beylik", "9f0b7c0a"], "d": ["Het moment waarop Osman Gazi van de Kayı-stam rond Söğüt en Domaniç zelfstandig begon op te treden, geldt traditioneel als het begin van de Osmaanse staat; sommige historici beschouwen de overwinning bij Bapheus in 1302 als het eigenlijke keerpunt. Dankzij zijn ligging aan de Byzantijnse grens groeide het beylik snel in macht door ghazi-strooptochten. In de context van het uiteenvallen van de Seltsjoekse erfenis verzamelde Osman Gazi ahi's, ghazi's en nomadische Turkmenen om zich heen; zijn band met sjeik Edebali wordt beschouwd als de basis van de morele legitimiteit van het beylik. Andere plaatsen die op dezelfde datum werden toegevoegd: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Verovering van Bursa", "98c727fa"], "d": ["Bursa, dat jarenlang geblokkeerd was, gaf zich over aan Orhan Gazi, die de laatste fase van het beleg leidde; de stad werd de eerste grote hoofdstad van het beylik. Volgens de overlevering werd het nieuws van de verovering aan de stervende Osman Gazi gebracht; Osman Gazi werd conform zijn testament in Bursa begraven. De stad werd snel voorzien van moskeeën, imarets en madrasa's en werd het model voor het vroege Osmaanse stedenbouwkundige beleid.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Verovering van İznik", "a846a811"], "d": ["İznik (Nicaea), een van de belangrijkste centra van Byzantium in Anatolië, gaf zich na de overwinning bij Pelekanon in 1329 over aan Orhan Gazi omdat het alle hoop op verzet had verloren. Hier werd de eerste Osmaanse madrasa gesticht en geleerden zoals Dâvûd-i Kayserî begonnen er les te geven; de stad werd het wetenschappelijk centrum van de vroege periode. De Hagia Sophia-kerk werd tot moskee omgevormd, een vroeg voorbeeld van de veroveringstraditie.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Verovering van İzmit", "06a35035"], "d": ["Met de val van İzmit (Nicomedia) kwam ook de laatste belangrijke vesting van Byzantium aan de Anatolische kant onder Osmaans bestuur; het hele schiereiland Kocaeli tot aan de overkant van Constantinopel werd Osmaans grondgebied. Zo beheerste het beylik de gehele zuid- en oostkust van de Zee van Marmara en legde het de basis voor de oversteek naar Rumelië.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Burcht Çimpe — oversteek naar Rumelië", "c2f0a07d"], "d": ["Süleyman Pasja, zoon van Orhan Gazi, had de burcht Çimpe, die hem tijdens de Byzantijnse burgeroorlog was gegeven, in 1352 als basis genomen; na de grote aardbeving die Gallipoli in maart 1354 verwoestte, werden de verlaten vestingen snel versterkt en werd het schiereiland een blijvende Osmaanse bruggenhoofd. Deze stap, ondersteund door de vestiging van uit Anatolië overgebrachte Turkmeense bevolking, vormt het begin van de Osmaanse aanwezigheid op het Europese continent, die meer dan 550 jaar zou duren.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Verovering van Edirne", "2f54ebb0"], "d": ["De inname van Edirne (Adrianopel), de sleutelstad van Thracië, bepaalde de hoofdbasis en de richting van de Balkanveroveringen; de datum van verovering is in de bronnen omstreden tussen 1361 en 1369. De stad werd kort daarna tot hoofdstad gemaakt, wat aankondigde dat het zwaartepunt van de staat naar Rumelië verschoof; het bleef ongeveer 90 jaar lang zetel van het rijk, tot de verovering van Constantinopel.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I besteeg de troon", "f8d48a26"], "d": ["Murad I (Hüdavendigâr), die na de dood van Orhan Gazi de troon besteeg, voerde de staat tijdens zijn regering van 27 jaar van een grensbeylik naar het skelet van een keizerrijk. Met het pençik-systeem werd de basis gelegd voor het Janitsarenkorps, het timar-stelsel werd verbreed, het beylerbeylik van Rumelië werd opgericht en de vizierschap werd versterkt. De Balkanveroveringen werden onder zijn bewind een systematische staatspolitiek.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Eerste Slag bij Kosovo — martelaarschap van Murad I", "10b8ddc9"], "d": ["De Balkanalliantie onder leiding van vorst Lazar werd op het Merelveld (Kosovo Polje) beslissend verslagen; Servië kwam onder Osmaanse opperheerschappij. Murad I, die het slagveld bezocht, werd door de Servische edelman Miloš Obilić met een dolk gedood — hij is de enige Osmaanse sultan die op het slagveld is omgekomen. In het legerkamp werd Yıldırım Bayezid in zijn plaats op de troon gezet; zijn broer Yakub Çelebi werd gewurgd, een van de eerste bekende voorbeelden van de praktijk van broedermoord.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Overwinning bij Nikopolis", "75716e96"], "d": ["Het grote kruisvaardersleger dat op oproep van de Hongaarse koning Sigismund was bijeengekomen, waaraan ook Frans-Bourgondische ridders deelnamen, werd bij Nikopolis aan de Donau door Yıldırım Bayezid zwaar verslagen. De overwinning bevestigde de Osmaanse overheersing over Bulgarije; gedurende een generatie kon er in Europa geen grote kruistocht meer worden georganiseerd.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Slag bij Ankara — begin van het Interregnum", "b4a99d96"], "d": ["In de zware nederlaag tegen het leger van Timur op de vlakte van Çubuk werd Yıldırım Bayezid gevangengenomen en hij stierf enkele maanden later in gevangenschap. Timur liet de Anatolische beyliks herrijzen; het Osmaanse grondgebied werd verdeeld onder de zonen van Bayezid en een 11 jaar durende troonstrijd (het Interregnum, Fetret Devri) begon. Deze periode, de zwaarste crisis sinds de oprichting van de staat, prentte het belang van een gecentraliseerde structuur in het Osmaanse geheugen. Andere plaatsen die op dezelfde datum verloren gingen: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delčev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofia, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Nikopol, Rusçuk, Thessaloniki, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çelebi Mehmed herstelde de eenheid", "03413dfd"], "d": ["In de laatste afrekening tussen de broers versloeg Mehmed I Mûsâ Çelebi bij Çamurlu en verenigde het grondgebied van het land onder één bestuur; daarom wordt hij beschouwd als de 'tweede stichter van de staat'. Tijdens zijn regering werd de aangetaste staatsstructuur hersteld, werden de betrekkingen met de Anatolische beyliks in evenwicht gebracht en werd in Rumelië een omzichtig vredesbeleid gevoerd.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Opstand van sjeik Bedreddin", "e0a072ca"], "d": ["De religieus-maatschappelijke beweging rond sjeik Bedreddin, een groot jurist en mysticus die tijdens het Interregnum kazasker was geweest, brak gelijktijdig uit met de opstanden van Börklüce Mustafa in Karaburun en Torlak Kemal in Manisa. De opstanden werden bloedig neergeslagen; Bedreddin werd in Deliorman gevangengenomen en in Serres geëxecuteerd. De gebeurtenis liet diepe sporen na in de literatuur en geschiedschrijving als de vroegste grote sociaal-messiaanse opstand in de Osmaanse geschiedenis.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Overwinning bij Varna", "f739eedc"], "d": ["Het Hongaars-Poolse kruisvaardersleger, dat het verdrag van Szeged had verbroken en naar het zuiden was getrokken, werd bij Varna vernietigd door Murad II, die was teruggekeerd aan het hoofd van het leger terwijl hij van de troon had afgezien; de jonge koning Ladislaus III sneuvelde op het slagveld. De overwinning nam de laatste grote kans op buitenlandse interventie om de Osmaanse aanwezigheid op de Balkan te liquideren weg en verzekerde de weg naar de verovering van Constantinopel.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Tweede Slag bij Kosovo", "ebe0b662"], "d": ["Het leger van János Hunyadi, dat wraak wilde nemen voor Varna, werd na een driedaagse verbeten strijd door Murad II beslissend verslagen. Dit is de laatste grote veldslag die de kruisvaarders op de Balkan tegen de Osmanen aangingen; met deze overwinning werd de Osmaanse heerschappij ten zuiden van de Donau onomkeerbaar gevestigd.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Verovering van Constantinopel", "583d5e3e"], "d": ["Na een beleg van vierenvijftig dagen (6 april–29 mei 1453) drong het Osmaanse leger op de ochtend van 29 mei over de muren de stad binnen; de laatste keizer Constantijn XI sneuvelde in de gevechten en het 1100 jaar oude Oost-Romeinse Rijk verdween uit de geschiedenis. De jonge sultan nam de titel 'Fâtih' (de Veroveraar) aan, maakte de stad tot hoofdstad en veranderde de Hagia Sophia in een moskee; de stad werd binnen korte tijd door vestiging en wederopbouw nieuw leven ingeblazen. Volgens de TDV werden Silivri en Vize pas in 1453 definitief veroverd; volgens het TDV-lemma Limnos kwam het eiland onmiddellijk na de verovering onder Osmaans bestuur en werd het onder voorwaarde van schatting aan de familie Gattilusio gelaten. In de atlas staan Silivri, Vize en Limnos vanaf deze dag van Byzantium naar het Osmaanse Rijk geschreven (Limnos als schatplichtig). Het gieten van reusachtige kanonnen, het over land slepen van schepen en de belegeringsopstelling voor de muren worden beschouwd als het toppunt van de militaire techniek van die tijd. De verovering geldt in de Europese geschiedschrijving als een van de symbolische data voor het einde van de Middeleeuwen.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Verovering van Trebizonde", "15f52403"], "d": ["Na een moeizame Zwarte Zee-veldtocht van Mehmed de Veroveraar, die gelijktijdig met leger en vloot werd gevoerd, gaf het Keizerrijk Trebizonde zich over; met het opruimen van dit laatste Byzantijnse restant in Anatolië kwam de gehele zuidkust van de Zwarte Zee onder Osmaanse heerschappij. Het beëindigen van de Komnenen-dynastie versterkte de aanspraak van de Veroveraar als 'heerser van twee zeeën en twee continenten'. Andere plaatsen die op dezelfde datum werden toegevoegd: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Definitieve verovering van Silifke — breken van het laatste verzet van de Karamanoğulları", "d988bee4"], "d": ["De burcht Silifke had zich in 1472 eenmaal overgegeven aan Gedik Ahmed Pasja, maar datzelfde jaar had Karamanoğlu Kasım Bey met hulp van de kruisvaardersvloot in de Middellandse Zee de burcht heroverd. Na de overwinning bij Otlukbeli droeg de Veroveraar zijn zoon en Gedik Ahmed Pasja op de regio definitief in te nemen; met hulp van de oude Osmaanse artilleristen werd het kruitmagazijn in brand gestoken en de burcht snel ingenomen. Zo werd het laatste verzet van de Karamanoğulları in het Taşeli-İçel-gebergte gebroken; de liquidatie van het beylik zou in 1474 worden voltooid.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Slag bij Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, de heerser van de Akkoyunlu, die in het oosten een grote macht was geworden en een bondgenootschap met Venetië had gesloten, werd bij Otlukbeli zwaar verslagen door het met vuurwapens uitgeruste leger van de Veroveraar. De overwinning bevestigde de Osmaanse superioriteit in Anatolië en was tevens een vroeg bewijs van de superioriteit van een centraal leger dat kanonnen en geweren gebruikte tegenover een klassiek leger. Volgens het TDV-lemma Gümüşhane stond de stad sinds 1467 onder Akkoyunlu-heerschappij; deze heerschappij eindigde met de nederlaag bij Otlukbeli en Gümüşhane kwam definitief onder Osmaanse heerschappij.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Krim komt onder Osmaanse bescherming", "44e3f7c8"], "d": ["De vloot onder bevel van Gedik Ahmed Pasja veroverde de zuidelijke kuststeden van de Krim, met name het Genuese Kaffa; deze kusten werden rechtstreeks Osmaanse sandjak. Het Krim-khanaat werd onder Mengli Giray een bevoorrechte vazalstaat die de Osmaanse opperheerschappij erkende en drie eeuwen lang een hoeksteen van de noordelijke politiek; de Zwarte Zee veranderde feitelijk in een Osmaanse binnenzee. Andere plaatsen die op dezelfde datum werden toegevoegd: Bahçesaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Dood van de Veroveraar — kwestie Cem Sultan", "190ecf01"], "d": ["Bij de plotselinge dood van de Veroveraar tijdens de veldtocht besteeg Bayezid II de troon; zijn broer Cem Sultan liet in Bursa op eigen aanspraak op het sultanaat de khutba in zijn naam lezen en munten slaan. Na zijn nederlaag vond hij eerst onderdak bij de Mamelukken en daarna bij de ridders van Rhodos; in handen van de ridders en het pausdom werd Cem een pasmunt in de Europese diplomatie en hij stierf in 1495 in Napels. Dit voorval dwong het Osmaanse buitenlandse beleid vijftien jaar lang tot voorzichtigheid.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Overwinning bij Çaldıran", "fea64ebb"], "d": ["Yavuz Sultan Selim, die de door de Safawidische propaganda in Anatolië ontstane dreiging bij de wortel wilde oplossen, bracht het leger van sjah Ismail op de vlakte van Çaldıran met zijn overwicht aan kanonnen en geweren een zware nederlaag toe. Tabriz werd binnengetrokken; Oost- en Zuidoost-Anatolië en de lijn Mosul–Diyarbakır werden bij het Osmaanse bestuur gevoegd. De aansluiting van de Koerdische beys bij de Osmanen dankzij de inspanningen van İdrîs-i Bitlisî legde het kader van de oostgrens vast dat eeuwenlang zou standhouden.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Overwinning bij Marj Dabiq", "07d254d3"], "d": ["Het Mamelukse leger werd binnen enkele uren bij Marj Dabiq, ten noorden van Aleppo, uiteengeslagen; de oude sultan Qansuh al-Ghawri stierf tijdens de slag. Met de overwinning, die de poorten van Aleppo en Damascus wijd opende, kwamen Syrië, Libanon en Palestina onder Osmaans bestuur; de weg naar de Egyptische veldtocht, die het einde van de Mamelukkenstaat zou betekenen, lag open.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniya — verovering van Egypte en het kalifaat", "caf378d6"], "d": ["Het Osmaanse leger stak snel de Sinaïwoestijn over, doorbrak de verdedigingslinie van Tumanbay bij Ridaniya en trok Caïro binnen; Tumanbay, die het verzet voortzette, werd gevangengenomen en geëxecuteerd en de Mamelukkenstaat verdween uit de geschiedenis. Egypte, de Hidjaz en de heilige steden kwamen onder Osmaans bestuur; de Abbasidische kalief en de heilige relieken werden naar Constantinopel gebracht. Met de overgang van het kalifaat naar de Osmaanse dynastie namen de sultans de aanspraak op het leiderschap van de islamitische wereld op zich; de controle over de Specerijenroute bezorgde het rijk ook grote inkomsten. Andere plaatsen die op dezelfde datum werden toegevoegd: Akko, Ma'an, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Süleyman de Wetgever besteeg de troon", "f6512269"], "d": ["De 46 jaar durende regering van Süleyman I, die na de dood van Yavuz als enige mannelijke erfgenaam de troon besteeg, wordt beschouwd als het politieke, militaire, juridische en culturele hoogtepunt van het rijk. Zijn kanunnames, die het gewoonterecht systematiseerden, bezorgden hem de titel 'Kanunî' (de Wetgever); in het Westen werd hij bekend als 'de Prachtige' (Magnificent). De werken van architect Sinan, de gouden eeuw van de divanliteratuur en de Middellandse Zee-overmacht van de vloot zijn de symbolen van deze periode.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Verovering van Belgrado", "59ef5cec"], "d": ["Belgrado, dat de Veroveraar in 1456 niet had kunnen innemen en dat gold als 'het slot van Midden-Europa', viel tijdens de eerste veldtocht van Süleyman na een beleg bij de samenvloeiing van Donau en Sava. De zuidelijke verdedigingslinie van Hongarije was daarmee ingestort; met deze verovering ging de deur open naar de Midden-Europese campagne die vijf jaar later naar Mohács en twintig jaar later naar de annexatie van Boeda zou leiden.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Verovering van Rhodos", "807bbb1e"], "d": ["Rhodos, de basis van de Johannieters die de zeeroutes van de oostelijke Middellandse Zee en de pelgrimsroute bedreigden, gaf zich na een maandenlang bloedig beleg bij verdrag over; de ridders kregen toestemming om de eilanden vrij te verlaten (later vestigden zij zich op Malta). De veiligheid van de Anatolische kusten was verzekerd en de zeeroute tussen Constantinopel en Egypte kwam onder ononderbroken Osmaanse controle.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Slag bij Mohács", "f3418b0d"], "d": ["Het Hongaarse leger werd op de vlakte van Mohács binnen ongeveer twee uur vernietigd door kanonvuur en manoeuvreeroverwicht; koning Lodewijk II kwam om in een moeras terwijl hij vluchtte. Mohács, een van de snelst gewonnen grote veldslagen uit de Osmaanse geschiedenis, maakte feitelijk een einde aan het onafhankelijke Hongaarse koninkrijk en opende het tijdperk van de Osmaans-Habsburgse rivaliteit in Midden-Europa.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Eerste Beleg van Wenen", "dc49ea4f"], "d": ["Tijdens de veldtocht die werd ondernomen tegen de Habsburgse aanspraken op de Hongaarse troon, belegerde het Osmaanse leger Wenen; omdat de zware kanonnen onderweg waren achtergelaten, de winter vroeg inviel en er bevoorradingsproblemen waren, werd het beleg na drie weken opgeheven. Hoewel de stad niet werd ingenomen, bleef de Osmaanse invloed in Hongarije behouden; Wenen markeerde de grens van de logistische reikwijdte van het rijk in Midden-Europa.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Verovering van Bagdad — Irakeyn-veldtocht", "897092c3"], "d": ["Tijdens de veldtocht naar 'de twee Irak' (Arabisch Irak en Perzisch Irak) werd eerst Tabriz en daarna zonder strijd Bagdad binnengetrokken; de inname van de oude hoofdstad van de Abbasiden bezorgde de Osmaanse heerser groot aanzien in de islamitische wereld. Het mausoleum van Imam-ı Âzam Ebû Hanîfe werd hersteld; met de toevoeging van Bagdad en Basra bereikte het Osmaanse grondgebied de Perzische Golf. Andere plaatsen die op dezelfde datum werden toegevoegd: Kirkoek, Kerbela.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Zeeslag bij Preveza", "30dc0f97"], "d": ["De door de paus aangevoerde kruisvaardersvloot werd ondanks haar numerieke overwicht bij Preveza uiteengeslagen door Barbarossa's tactiek, waarbij hij wind en kust meesterlijk benutte; Andrea Doria verliet het slagveld. De overwinning vestigde de onbetwiste Osmaanse zeemacht in de Middellandse Zee, die ongeveer 33 jaar zou duren; zij is de symbolische datum van de dag van de marine in de Turkse zeevaartstraditie. Andere plaatsen die op dezelfde datum werden toegevoegd: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annexatie van Boeda — Hongarije Osmaanse provincie", "db53b244"], "d": ["Nadat Süleyman op een veldtocht was uitgetrokken vanwege de Habsburgse belegering van Boeda, nam hij na de bevrijding van de stad Midden-Hongarije rechtstreeks onder Osmaans bestuur en stichtte het beylerbeylik Boeda; Transsylvanië werd een autonoom prinsdom onder Osmaanse bescherming. Deze driedeling van Hongarije duurde ongeveer 150 jaar en vormde het blijvende Osmaanse bestuurlijke skelet in Midden-Europa.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Vrede van Amasya", "a5afe0d1"], "d": ["Dit is het eerste officiële vredesverdrag dat een einde maakte aan de jarenlange Osmaans-Safawidische oorlogen. Bagdad en Irak bleven Osmaans, de grens in Oost-Anatolië werd voor het eerst wederzijds erkend; de Safawiden namen op zich de sjiitische propaganda in Osmaans gebied te staken, de Osmanen de veiligheid van Iraanse pelgrims bij doorreis. Het verdrag werd het eerste voorbeeld van een juridisch kader voor de betrekkingen tussen beide staten.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — overlijden van Süleyman de Wetgever", "e2917ed2"], "d": ["De 72-jarige Süleyman stierf in zijn tent, enkele uren voor de val van de burcht Szigetvár die hij tijdens zijn dertiende veldtocht belegerde; Sokollu Mehmed Pasja hield de dood weken geheim opdat het leger niet uiteen zou vallen. De burcht werd ingenomen, maar de staat had zijn langstregerende en meest luisterrijke sultan verloren; zijn zoon Selim II besteeg de troon en het gewicht van de grootveziers in het staatsbestuur begon toe te nemen.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Verovering van Cyprus", "e364a2b3"], "d": ["In 1570 werd een landing uitgevoerd op het door Venetië bestuurde Cyprus; Nicosia viel snel, Famagusta gaf zich pas na een beleg van elf maanden over in augustus 1571. Het eiland, cruciaal voor de veiligheid van de handels- en pelgrimsroutes in de oostelijke Middellandse Zee, werd als beylerbeylik georganiseerd en met bevolking uit Anatolië bevolkt; de verovering was ook de aanleiding voor de grote kruisvaardersalliantie die tot Lepanto zou leiden.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Nederlaag bij Lepanto (İnebahtı)", "6a1d44a9"], "d": ["De kruisvaardersvloot, die zich na de verovering van Cyprus had verenigd, onderschepte de Osmaanse vloot in de baai van Lepanto en vernietigde het grootste deel ervan; kapudan pasja Müezzinzâde Ali Pasja sneuvelde en alleen de vloot van Uluç Ali bleef gespaard. Na de ramp benoemde grootvizier Sokollu Mehmed Pasja Uluç Ali Pasja tot kapudan pasja met de opdracht de verspreide vloot te verzamelen en liet hij op alle scheepswerven van Constantinopel tot Alanya een nieuwe vloot bouwen; toch was de absolute superioriteit in de Middellandse Zee psychologisch aangetast.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Slag bij Mezőkeresztes", "da308ec5"], "d": ["In de grootste veldslag van de Lange Oorlog (1593–1606) herstelde het leger, waarvan Mehmed III zelf het bevel voerde, zich op het punt van uiteenvallen dankzij de aansporing van Hoca Sâdeddin Efendi en bracht het het Habsburgse leger een nederlaag toe. Zij geldt als de laatste grote klassieke veldslag die de Osmanen wonnen; dat de slag het algemene verloop van de oorlog niet veranderde, werd echter gezien als een teken van de slijtage van het militaire stelsel.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Vrede van Zsitvatorok", "39c01142"], "d": ["Met het verdrag dat een einde maakte aan de dertien jaar durende uitputtingsoorlog werd de Habsburgse heerser voor het eerst als 'Romeins keizer' als gelijke van de sultan beschouwd en werd de jaarlijkse schatting afgeschaft. Het gebiedsverlies was nagenoeg nihil; maar deze verandering in diplomatiek taalgebruik wordt gelezen als symbool van het einde van de Osmaanse aanspraak op absolute superioriteit tegenover Europa.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Verdrag van Qasr-i Shirin", "c1acf3af"], "d": ["Het verdrag dat werd gesloten nadat Murad IV Bagdad had heroverd (1638), beëindigde de meer dan honderd jaar durende Osmaans-Safawidische oorlogen. Bagdad en Irak bleven definitief Osmaans, Revan werd aan de Safawiden gelaten; de getrokken lijn werd met kleine wijzigingen de basis van de huidige grens tussen Turkije en Iran en geldt als een van de langstlevende grenzen ter wereld. Het verdrag liet Badra, Jassan, Mandali, Derteng en Derna aan de Osmanen; de grensvesting Zencir zou worden afgebroken, de dorpen ten westen ervan bleven Osmaans, die ten oosten ervan Iraans. De omgeving van de Zalim-burcht bij Şehrizor en Kızılca Kale bleven Osmaans, Avroman en Mihriban bleven Iraans; de burchten Kotur, Makû en Mağazberd zouden door beide partijen worden afgebroken.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Verovering van Kreta voltooid", "e0d85604"], "d": ["Het beleg van Candia, het laatste bedrijf van de Kretenzische oorlog die in 1645 begon, werd afgesloten met de driejarige vastberaden campagne van Fâzıl Ahmed Pasja; de Venetiaanse commandant Morosini droeg de stad bij verdrag over. De strijd van ongeveer een kwart eeuw ging de geschiedenis in als het langste beleg uit de Osmaanse geschiedenis; ook het laatste grote Latijnse bolwerk van de oostelijke Middellandse Zee kwam onder Osmaans bestuur. Drie kleine rotsvestingen aan de noordkust van het eiland — Souda, Spinalonga en Grambousa — bleven nog Venetiaans; omdat zij op afzonderlijke eilandjes liggen, kunnen zij op de kaart niet los van de rest van Kreta worden weergegeven.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Verdrag van Buczacz — grootste uitgestrektheid", "b17b6e5a"], "d": ["Met het Verdrag van Buczacz, gesloten na de verovering van Kamjanets-Podilsky tijdens de Poolse veldtocht, werd Podolië bij het Osmaanse Rijk gevoegd en een deel van Oekraïne onder bescherming genomen. Het rijk bereikte zo zijn grootste uitgestrektheid in Europa; dit punt wordt beschouwd als het hoogtepunt van het tijdperk van expansie en tegelijk als de laatste schakel ervan.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Mislukking van het Tweede Beleg van Wenen", "7d889252"], "d": ["Het twee maanden durende beleg van Wenen door Merzifonlu Kara Mustafa Pasja eindigde in een nederlaag door de plotselinge aanval die de Poolse koning Jan Sobieski vanaf de Kahlenberg inzette; het leger trok zich terug en liet zijn bagage achter, Merzifonlu werd in Belgrado geëxecuteerd. De oorlog die volgde op de na deze overwinning gevormde Heilige Liga duurde 16 jaar; deze nederlaag wordt aangewezen als het beginmoment van de grote achteruitgang in de Osmaanse geschiedenis.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Verovering van de burcht Grambousa — een van de rotsvestingen van Kreta die Venetiaans bleven", "3ddf9eeb"], "d": ["Hoewel de verovering van Kreta met de overgave van Candia in 1669 grotendeels voltooid werd geacht, bleef de rotsachtige eilandvesting Grambousa aan de noordwestpunt van het eiland nog drieëntwintig jaar in Venetiaanse handen. Met de inname ervan in 1692 werd een van de drie Venetiaanse overblijfselen op Kreta opgeruimd; Souda en Spinalonga zouden de Morea-veldtocht van 1715 moeten afwachten.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Vrede van Karlowitz — eerste grote gebiedsverlies", "8f7e2546"], "d": ["Met Karlowitz, dat een einde maakte aan de zestien jaar durende oorlogen van de Heilige Liga, werden Hongarije en Transsylvanië aan Oostenrijk, Podolië aan Polen en de Morea en de kust van Dalmatië aan Venetië gelaten. Voor het eerst in de Osmaanse geschiedenis ging grondgebied op deze schaal aan de onderhandelingstafel en blijvend verloren; het verdrag wordt beschouwd als het inleidende document van het nieuwe tijdperk waarin het rijk tegenover Europa in de verdediging ging, en is ook een keerpunt in de Osmaanse diplomatieke geschiedenis. Plaatsen die op dezelfde dag in de atlas van hand wisselden: Kostajnica en Jasenovac (van de Osmanen naar de Habsburgers; de verdragstekst laat Castanoviz in handen van de keizer, de overdrachtsdag van Jasenovac staat niet in de bron, de verdragsdag is ingevuld) en Preveza (van Venetië naar de Osmanen; TDV karlofca: volgens de bepaling die op 24 Receb 1110 / 26 januari 1699 werd ondertekend, werden de door Venetië bezette plaatsen ten noorden van de Golf van Lepanto teruggegeven). De atlas schrijft Kostajnica en Jasenovac bovendien aan de Habsburgse kant toe, Uman en Vinnytsia in Rechteroever-Oekraïne van de Osmanen aan Polen (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: 1672-99 Turkse heerschappij) en Nadin in Dalmatië aan Venetië (een plaatsspecifieke overdrachtsdag staat niet in de bron, de verdragsdag is ingevuld; de periodegrenzen van Nadin zijn niet met een bron bevestigd — verklaarde benadering). Ook Vonitsa ten noorden van de Golf van Lepanto wordt van Venetië aan de Osmanen teruggegeven (TDV karlofca); in Dalmatië behoort Vrana (Urana) tot de plaatsen die Venetiaans bleven (periodegrens niet bevestigd — verklaard).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Overwinning bij de Proet", "2583572f"], "d": ["Vanwege de kwestie van de Zweedse koning, die na de nederlaag bij Poltava bij de Osmanen onderdak had gezocht, werd in de oorlog die uitbrak het leger van tsaar Peter I aan de oever van de Proet omsingeld en gedwongen zich over te geven. Met het gesloten verdrag werd Azak teruggenomen; dat het leger niet werd vernietigd en de tsaar vrij werd gelaten, ging de geschiedenis in als een beslissing waarover tot op de dag van vandaag wordt gediscussieerd.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Verovering van de burchten Souda en Spinalonga — uitwissing van het laatste Venetiaanse spoor op Kreta", "7261f7ba"], "d": ["Drieëntwintig jaar na de val van Grambousa in 1692 werden met een zijtak van de Morea-veldtocht ook de burchten Souda en Spinalonga, de laatste twee steunpunten van Venetië op Kreta, veroverd. Zo was de verovering van Kreta, die in 1645 begon, na zesenveertig jaar tot op de laatste centimeter van het eiland voltooid.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Opstand van Patrona Halil", "100941a4"], "d": ["De mislukking aan het Iraanse front, de belastingen en de woede over de weelde in de kringen rond het paleis ontaardden onder leiding van de badhuisknecht Patrona Halil in een grote opstand. Grootvizier İbrahim Pasja werd gedood, Ahmed III werd afgezet en het Tulpentijdperk kwam ten einde; dat de opstandelingen maandenlang over de stad heersten, toonde op treffende wijze de kwetsbaarheid van het centrale gezag.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Verdrag van Belgrado — herovering van Belgrado, Smederevo en Noord-Servië", "ba7f8e46"], "d": ["Aan het einde van de oorlog die aan twee fronten tegen Oostenrijk en Rusland werd gevoerd (1736–1739) werden Belgrado en Noord-Servië heroverd; Rusland nam op zich Azak te ontmantelen en geen vloot op de Zwarte Zee te hebben. Het verdrag, beschouwd als het laatste grote succes van de Osmaanse diplomatie en het Osmaanse leger in de 18e eeuw, bezorgde het rijk een vredesperiode van een kwart eeuw. Andere plaatsen die op dezelfde dag in de atlas van Oostenrijk naar de Osmanen terugkeerden: Hisarcık (Grocka) (abi-centrumketen van Belgrado; TDV belgrad), Craiova, Râmnicu Vâlcea (Rimnik) en Turnu Severin (terugkeer van Klein-Walachije naar de Osmanen, naar het vazalschap van Walachije). Bosanski Brod en Bosanska Dubica in de Sava-strook keren in de atlas op 28 september 1739 terug naar de Osmanen (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 september 1739). Ook Târgu Jiu in Klein-Walachije keert op dezelfde dag terug naar de Osmanen.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Overval bij Çeşme", "840b30bd"], "d": ["De Russische vloot, die met Engelse steun de Middellandse Zee had bereikt, overviel de Osmaanse vloot in de haven van Çeşme waar zij beschutting had gezocht met brandschepen en verbrandde haar nagenoeg volledig. Rusland verscheen voor het eerst als grote zeemacht in de Middellandse Zee; de ramp was een van de slagen die het lot van de oorlog naar Küçük Kaynarca in 1774 bepaalden en maakte de behoefte aan een grondige hervorming van de vloot duidelijk.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Verdrag van Küçük Kaynarca", "2776dcdb"], "d": ["Met Küçük Kaynarca, dat de oorlog van 1768–1774 beëindigde en geldt als een van de zwaarste verdragen uit de Osmaanse geschiedenis, kreeg het Krim-khanaat 'onafhankelijkheid' — in feite werd een Russische invloedssfeer geschapen. Rusland vestigde zich aan de Zwarte Zeekust, verkreeg het doorvaartrecht door de Zeestraten voor koopvaardijschepen en een permanente ambassade in Constantinopel; de vage bepaling over bescherming van de orthodoxe onderdanen opende de deur naar de interventiegronden van de volgende eeuw. Voor het eerst werd een gebied met een islamitische bevolking aan de Osmaanse heerschappij onttrokken.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annexatie van de Krim door Rusland", "bdf6faa8"], "d": ["De door Küçük Kaynarca geschapen 'onafhankelijke' Krim werd, onder het voorwendsel van de onrust tijdens de regering van de laatste khan Şahin Giray, bij manifest van Catharina II door Rusland geannexeerd. Het driehonderd jaar durende Osmaans-Krim-partnerschap kwam ten einde; het verlies van de noordelijke steppen nam de verdedigingsdiepte van Constantinopel weg en zette de eerste grote migratiegolf van tienduizenden Krimtataren naar Osmaans grondgebied in gang. Op deze dag werd het Krim-schiereiland (Alushta, Kaffa, Soedak, Jalta, Balaklava, Inkerman, Mangoep, Arabat) bij Rusland gevoegd; Taman en Koeban gingen bij dezelfde annexatie ook naar Rusland (TDV Kırım: 8 april 1783 Juliaans = 19 april Gregoriaans).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III en de Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, die midden in de oorlog de troon besteeg, begreep dat de nederlagen structureel waren en startte onder de naam 'Nizâm-ı Cedîd' (Nieuwe Orde) een omvattend hervormingsprogramma: een nieuw leger dat naar Europees model werd getraind, een afzonderlijke schatkist om dit te financieren (Îrâd-ı Cedîd), versterking van de ingenieursscholen en de eerste permanente ambassades in de Europese hoofdsteden. Het programma wordt beschouwd als het begin van de moderne Turkse hervormingstraditie; door het verzet van de korpsen en de ayans zou het in 1807 ten val komen.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidatie van de Maltezer ridders — tussenstop van de Franse vloot", "d62f901d"], "d": ["De Franse vloot op weg naar Egypte deed Malta aan; de Sint-Jansridders (Malta) droegen het eiland zonder veel verzet over. De laatste burcht van de ridderorde die in 1522 uit Rhodos was verdreven en zich hier had gevestigd, kwam zo ten einde. Malta zou twee jaar later in Britse handen vallen, terwijl Napoleon vanaf het eiland rechtstreeks naar Alexandrië koers zette.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Napoleons bezetting van Egypte", "93fede5f"], "d": ["Het leger van generaal Bonaparte landde bij Alexandrië en bezette Egypte; deze veldtocht, gericht op de Britse route naar India, was de eerste directe aanval van een Europese mogendheid op het kerngebied van het Osmaanse Rijk. Nelsons overval bij Aboukir en Cezzâr Ahmed Pasja's verdediging van Akko braken de Franse opmars; de bezetting eindigde in 1801, maar in het vacuüm dat zij achterliet begonnen de opkomst van Mehmed Ali Pasja van Kavala en het tijdperk van de 'Oosterse kwestie'.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Document dat onder leiding van Alemdar Mustafa Pasja, de ayan van Rusçuk die Mahmud II op de troon bracht, werd ondertekend tussen het paleis en de machtige ayanfamilies in de provincie; de ayans beloofden de sultan trouw en militaire steun, terwijl de staat hun bestaan en rechten erkende. Omdat het het eerste voorbeeld in de Osmaanse geschiedenis was van beperking van het gezag van de sultan door een document, wordt het door sommige historici beschouwd als het verre begin van de constitutionele traditie; in de praktijk raakte het binnen enkele maanden buiten werking.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Griekse opstand begon", "a7293715"], "d": ["De opstand die door de organisatie Filiki Eteria werd voorbereid brak eerst uit in Walachije en vervolgens, met zijn eigenlijke kracht, in de Morea; de staat, die bezig was met de kwestie van Tepedelenli Ali Pasja, reageerde aanvankelijk te laat. Dankzij de intense Griekse sympathie in de Europese publieke opinie (filhellenisme) groeide de opstand snel uit tot een internationale zaak; zo werd de lont ontstoken voor de eerste succesvolle onafhankelijkheidsbeweging op Osmaans grondgebied in het tijdperk van het nationalisme. Andere plaatsen die op dezelfde datum verloren gingen: Athene, Balyabadra (Patras), İstefe (Thebe), Livadya, Eleusis (Attica), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Eerste gewapende opstand in de Morea", "77e6250f"], "d": ["Na de oversteek van de Proet sloeg de opstand over naar de Morea: de gewapende actie die in Kalavryta begon (Juliaans 21 maart) werd gevolgd door bewegingen in Patras, Kalamata en Mani; de Morea veranderde snel in een algemene opstand en het Osmaanse bestuur verloor het grootste deel van het schiereiland. Andere plaatsen die op dezelfde datum verloren gingen: Athene, Balyabadra (Patras), İstefe (Thebe), Livadya, Eleusis (Attica), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — Janitsarenkorps afgeschaft", "08c9372a"], "d": ["De janitsaren, die de ketels omkeerden tegen de training van het nieuw gevormde Eşkinci-korps, werden in hun kazernes op het Etmeydanı vernietigd door het kanonvuur van de door Mahmud II van tevoren voorbereide getrouwe troepen; het korps werd samen met al zijn takken en de verbonden Bektashi-tekkes opgeheven. Deze operatie, die onder de naam 'Gelukkige Gebeurtenis' de geschiedenis inging, liquideerde een vier eeuwen oude instelling en maakte de weg vrij voor het leger van de Asâkir-i Mansûre-i Muhammediyye en alle latere centralisatiehervormingen.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Overval bij Navarino", "ee579e7f"], "d": ["De Osmaans-Egyptische vloot, die bezig was de Griekse opstand neer te slaan, werd bij Navarino verbrand door de gecombineerde Brits-Frans-Russische vloot die zonder oorlogsverklaring de haven binnenvoer; bijna zestig schepen en duizenden zeelieden gingen verloren. De overval, die in de Europese diplomatie werd weggewuifd als een 'ongelukkig voorval', waarborgde feitelijk de Griekse onafhankelijkheid en opende de weg naar de Osmaans-Russische oorlog van 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Edict van Tanzimat", "5042ce7b"], "d": ["Met het in Gülhane voorgelezen Hatt-ı Hümâyun werden de veiligheid van leven, eigendom en eer van alle onderdanen, zonder onderscheid van godsdienst, onder staatsgarantie gebracht; de beginselen van rechtvaardigheid in de belasting, ordelijkheid in de dienstplicht en geen straf zonder proces werden afgekondigd. Het edict, het werk van Mustafa Reşid Pasja, wordt beschouwd als het eerste grote document van constitutionele aard van de Osmaanse modernisering en gaf zijn naam aan het hervormingstijdperk 'Tanzimat-periode' (1839–1876); in dit kader werden grondige herstructureringen doorgevoerd in bestuur, recht, onderwijs en financiën.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Krimoorlog begon", "3b9ca3c8"], "d": ["De crisis, begonnen met de kwestie van de heilige plaatsen en de Russische aanspraak op bescherming van de orthodoxe onderdanen, ontaardde in open conflict met de Osmaanse oorlogsverklaring; na de overval bij Sinope traden Engeland en Frankrijk (later Piëmont) aan Osmaanse zijde in de oorlog. De oorlog werd met de landing van de geallieerde legers op de Krim en de inname van Sebastopol gewonnen met het Verdrag van Parijs in 1856; maar de eerste buitenlandse lening, in de oorlogsjaren aangegaan (1854), bracht het rijk in een spiraal van financiële afhankelijkheid die een halve eeuw zou duren.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Hervormingsedict (Islahat Fermanı)", "78ff234d"], "d": ["Het edict, afgekondigd voor de vredesonderhandelingen van Parijs, breidde de beginselen van de Tanzimat uit en kende aan niet-moslimonderdanen brede gelijkheidsrechten toe, waaronder ambtenarenposten, militaire dienst en het openen van scholen; de gemeenschapsorganisaties werden herordend. Met het daarna ondertekende Verdrag van Parijs werd de Osmaanse staat formeel toegelaten tot de familie van het Europese volkenrecht en kwam zijn territoriale integriteit onder de gezamenlijke garantie van de grote mogendheden — in de praktijk zou deze garantie een nieuwe deur voor interventies worden.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — Eerste Constitutionele Periode", "0fe052c1"], "d": ["Op de dag dat de internationale conferentie die in Constantinopel bijeen was gekomen om de Balkancrisis te bespreken werd geopend, werd met kanonschoten de eerste Osmaanse grondwet afgekondigd; met de Kanûn-ı Esâsî, het werk van de beweging van de 'Jonge Osmanen' onder leiding van Midhat Pasja, werd een tweekamerparlement gevormd. De Meclis-i Meb'ûsan werd in maart 1877 geopend; maar Abdülhamid II schorste het parlement in februari 1878 voor onbepaalde tijd met de Oorlog van '93 als reden en de grondwet bleef dertig jaar opgeschort.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Oorlog van '93 (Osmaans-Russische oorlog van 1877–78)", "5bd96af7"], "d": ["In de oorlog die de 'Oorlog van '93' werd genoemd omdat hij overeenkwam met het jaar 1293 van de Rûmî-kalender, vielen de Russische legers aan twee fronten aan; hoewel Gazi Osman Pasja's verdediging van Plevna en de Kaukasische veldslagen van Ahmed Muhtar Pasja legendarisch werden, bezweek het front en rukten de Russen op tot Yeşilköy (San Stefano). De oorlog zette de grote golven van moslimmigratie van de Balkan en de Kaukasus naar Constantinopel in gang, waarvan de gevolgen tot op heden doorwerken; de demografische en financiële structuur van het rijk kwam nooit meer terug in de oude staat.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Verdrag van Berlijn", "47f76a49"], "d": ["Het Congres van Berlijn, dat het door San Stefano ontstane 'Groot-Bulgarije' in naam van het evenwicht tussen de grote mogendheden herzag, liet toch een zwaar beeld achter: Servië, Montenegro en Roemenië werden onafhankelijk; het autonome Prinsdom Bulgarije werd gesticht; Bosnië-Herzegovina werd aan de Oostenrijkse bezetting, Cyprus aan het Britse bestuur en Kars-Ardahan-Batoem aan Rusland gelaten. De vijfhonderd jaar oude Osmaanse orde in Rumelië viel grotendeels uiteen; de 'Oosterse kwestie' werd een permanent onderwerp op de agenda van de Europese diplomatie. Andere plaatsen die op dezelfde datum verloren gingen: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Boekarest, Iași, Köstence. Roemenië, dat Bessarabië aan Rusland moest afstaan, kreeg Tulcea en Dobroedzja: Tulcea, Babadag, Măcin, Isaccea, Hârșova en Mangalia in Noord-Dobroedzja gingen over naar Roemenië.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Bezetting van Tunesië en Düyûn-ı Umûmiyye", "c7e25598"], "d": ["Frankrijk bezette Tunesië onder voorwendsel van de incidenten aan de Algerijnse grens en nam het met het Verdrag van Bardo onder zijn bescherming; de Osmaanse aanwezigheid in Noord-Afrika werd teruggebracht tot Tripolitanië. Met het Muharrem-decreet, uitgevaardigd in hetzelfde jaar, werd de Düyûn-ı Umûmiyye-administratie opgericht voor het beheer van de bankroete buitenlandse schulden, waarin de schuldeisers vertegenwoordigd waren: basisinkomsten zoals zout, tabak en zijde werden rechtstreeks aan dit buitenlandse bestuur gekoppeld en de financiële soevereiniteit werd zwaar beperkt. Andere plaatsen die op dezelfde datum verloren gingen: Kairouan, Gabès, Sfax, Djerba.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Britse bezetting van Egypte", "f1269768"], "d": ["De Urabi Pasja-beweging, die in Egypte opkwam tegen het financiële faillissement en buitenlandse controle, werd na het bombardement op Alexandrië verpletterd door de overwinning bij Tel el-Kebir van het aan land gegane Britse leger en Caïro werd bezet. Hoewel Egypte juridisch aan het Osmaanse Rijk gebonden bleef, kwam het feitelijk onder Brits bestuur; de controle over het Suezkanaal werd het middelpunt van de Britse imperiale strategie.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Afkondiging van de Tweede Constitutionele Periode", "95ee2fd2"], "d": ["Tegenover de beweging die groeide doordat officieren van het Comité voor Eenheid en Vooruitgang in Macedonië de bergen introkken, herstelde Abdülhamid II de Kanûn-ı Esâsî; de 'afkondiging van de vrijheid' werd met enthousiasme ontvangen en er werden verkiezingen gehouden. Toch kwam er geen stabiliteit: nadat het Incident van 31 maart (april 1909) was onderdrukt, werd Abdülhamid afgezet; ook de onafhankelijkheid van Bulgarije, de annexatie van Bosnië en de oriëntatie van Kreta op Griekenland vonden in deze roerige maanden plaats.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Italiaans-Turkse Oorlog (Tripolitaanse Oorlog)", "ed441994"], "d": ["Het koloniaal ingestelde Italië verklaarde de oorlog aan Tripolitanië, het laatste Osmaanse gebied in Noord-Afrika, en bezette de kusten; toen de staat zonder vloot geen reguliere troepen kon sturen, trokken jonge officieren zoals Mustafa Kemal en Enver Bey in het geheim naar de regio en organiseerden met de Senoessi-stammen een effectief verzet. Met het Verdrag van Ouchy (18 oktober 1912), dat werd ondertekend na het uitbreken van de Balkanoorlog, werd Libië aan Italië gelaten; Italië bezette bovendien Rhodos en de Dodekanesos.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Verdrag van Londen — verlies van Rumelië", "f3f976df"], "d": ["Met het Verdrag van Londen, dat de Eerste Balkanoorlog beëindigde, gingen alle gebieden ten westen van de lijn Midye-Enez en de Egeïsche eilanden verloren; Albanië werd onafhankelijk. Van Rumelië, dat al meer dan vijfhonderd jaar het demografische, economische en culturele zwaartepunt van het rijk was, zou alleen Oost-Thracië overblijven (Edirne werd in de Tweede Balkanoorlog heroverd); het verlies verhardde het oorlogs- en vestigingsbeleid van het Unionistische bestuur ingrijpend. De volgende plaatsen ten westen van de lijn Midye-Enez gingen verloren: Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Debar), Prizren, Priştine, Peç (Peja), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje); Serez, Drama, Kavala, Petriç, Nevrokop, İskeçe, Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); op Kreta Chania, Candia, Kreta (Rethymno), Sitia (Sitiye) en Sfakia (İsfakiye).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Toetreding tot de Eerste Wereldoorlog", "05a0252e"], "d": ["Dat de aan Engeland ontsnapte pantserschepen Goeben en Breslau als gekocht werden voorgesteld en de Zeestraat binnen mochten, trok de staat stap voor stap naast Duitsland; toen de vloot onder bevel van admiraal Souchon Russische havens bombardeerde (29 oktober) begon de oorlog feitelijk, en de wederzijdse verklaringen volgden begin november. Ondanks de afkondiging van de Grote Jihad bleef het verwachte effect uit; het rijk raakte vier jaar lang op vijf afzonderlijke fronten, van de Kaukasus tot Palestina, verwikkeld in een strijd om het bestaan.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Overwinning bij Çanakkale (Gallipoli)", "95d888e8"], "d": ["De geallieerde armada, die Constantinopel wilde laten vallen en Rusland wilde bereiken, werd op 18 maart door het vuur van de mijnenvelden en forten uit de Zeestraat teruggeslagen; de door het mijnenlegger Nusret gelegde mijnenlinie bepaalde het lot van de strijd. Ook de landoperatie op Gallipoli, begonnen in april, werd bij Anafartalar en Conkbayırı tot staan gebracht; de geallieerden ontruimden het schiereiland in januari 1916 volledig. Luitenant-kolonel Mustafa Kemal maakte zich aan dit front een naam; de overwinning, behaald tegen een prijs van ongeveer een kwart miljoen gesneuvelden en vermisten, wordt beschouwd als de geboorteplaats van de kaders en de geest van de Nationale Strijd.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Opstand van sjerif Hoessein", "75f7c58c"], "d": ["De emir van Mekka, sjerif Hoessein, kwam na geheime briefwisseling met de Britten in opstand met de belofte van een onafhankelijk Arabisch koninkrijk; de Hidjaz-spoorlijn werd doelwit van aanvallen. Hoewel Fahreddin Pasja's legendarische verdediging van Medina, die tot na de wapenstilstand voortduurde, een symbool van verzet bleef, versnelde de opstand, in combinatie met de Britse opmars aan het Palestijnse front, het uiteenvallen van de Osmaanse heerschappij in de Arabische provincies. Andere plaatsen die op dezelfde datum verloren gingen: Ta'if.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Wapenstilstand van Moudros", "9e87c767"], "d": ["De Osmaanse staat, wiens fronten door de ineenstorting van Bulgarije van elkaar waren afgesneden, trok zich terug uit de oorlog met de wapenstilstand die aan boord van het pantserschip Agamemnon werd getekend. Artikel 7, dat de opening van de Zeestraten toestond en de bezetting van plaatsen die de veiligheid bedreigden mogelijk maakte, werd binnen korte tijd het juridische deksel op de feitelijke verdeling: Mosul, Iskenderun, daarna Smyrna en Constantinopel werden bezet. De wapenstilstand wordt beschouwd als het document van het feitelijke einde van het rijk. Andere plaatsen die op dezelfde datum verloren gingen: Hama, Damascus, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal in Samsun — Nationale Strijd", "09a8f784"], "d": ["In het klimaat van verontwaardiging door de bezetting van Smyrna ging Mustafa Kemal Pasja, in de hoedanigheid van inspecteur van het 9e Leger, in Samsun aan land en richtte zijn officiële taak op het organiseren van het verzet in Anatolië. De Circulaire van Amasya en de congressen van Erzurum en Sivas zijn het vervolg van deze stap; het beginsel 'de onafhankelijkheid van de natie zal opnieuw door de vastberadenheid en het besluit van de natie worden gered' werd de kern van het politieke programma van de Nationale Strijd.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Opening van de TBMM en Sèvres", "2008feec"], "d": ["Na de formele bezetting van Constantinopel en de ontbinding van de Meclis-i Meb'ûsan werd op 23 april 1920 in Ankara de Grote Nationale Vergadering geopend; de vergadering, die buitengewone bevoegdheden in zich verenigde, werd de kern van de nieuwe staat gebaseerd op de nationale wil. Het in augustus door de regering van Constantinopel ondertekende Verdrag van Sèvres verdeelde Anatolië; de TBMM verklaarde de ondertekenaars tot vaderlandsverraders en Sèvres werd nooit uitgevoerd.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Slag aan de Sakarya", "f2f970a6"], "d": ["Het Griekse offensief, dat tot op 50 kilometer van Ankara naderde, werd gebroken in de 22 dagen en 22 nachten durende slag die werd gevoerd onder het bevel 'er is geen verdedigingslinie, er is een verdedigingsvlak' van Mustafa Kemal Pasja, die de bevoegdheid van opperbevelhebber had overgenomen. Het Griekse leger ging voor het eerst over op strategische verdediging; de overwinning bezorgde Mustafa Kemal de titels gazi en müşir (maarschalk) en opende de deur naar het Verdrag van Ankara met Frankrijk en erkenning door het buitenland.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Groot Offensief en bevrijding van Smyrna", "172a50c4"], "d": ["Het offensief dat op de ochtend van 26 augustus vanaf Kocatepe werd ingezet, bereikte op 30 augustus bij Dumlupınar met de Slag van de Opperbevelhebber de vernietiging van de belangrijkste Griekse strijdkrachten; met de achtervolging onder het bevel 'Legers, uw eerste doel is de Middellandse Zee, vooruit!' werd Smyrna op 9 september bevrijd. Met de Wapenstilstand van Mudanya (11 oktober) werd Oost-Thracië zonder strijd teruggenomen; de militaire overwinning bepaalde de onderhandelingskracht van de nieuwe staat die in Lausanne zou worden gevestigd.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Afschaffing van het sultanaat", "9f36a9f6"], "d": ["Nadat ook de regering van Constantinopel was uitgenodigd voor de besprekingen in Lausanne, schafte de TBMM op 1 november 1922 het sultanaat af door sultanaat en kalifaat te scheiden; de 623 jaar durende Osmaanse dynastieke heerschappij kwam juridisch ten einde. Mehmed VI Vahideddin verliet op 17 november met een Brits oorlogsschip het land; Abdülmecid Efendi werd bij besluit van de TBMM tot het kalifaat benoemd en ook dit ambt zou op 3 maart 1924 worden afgeschaft.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Verdrag van Lausanne", "38c27f7d"], "d": ["Met het Vredesverdrag van Lausanne, ondertekend na acht maanden moeizame onderhandelingen, werden de grenzen, de volledige onafhankelijkheid en de soevereiniteit van de nieuwe Turkse staat internationaal erkend; de capitulaties werden afgeschaft, de Düyûn-ı Umûmiyye werd in liquidatie gebracht en de bevolkingsuitwisseling werd geregeld. Lausanne, dat Sèvres feitelijk nietig maakte, wordt beschouwd als de diplomatieke overwinning van de Nationale Strijd en als het stichtende buitenlandse document van de Republiek.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Uitroeping van de Republiek", "d5bfcdfb"], "d": ["Nadat de TBMM met een grondwetswijziging de bepaling 'de regeringsvorm van de Turkse Staat is de republiek' had aangenomen, werd de Republiek uitgeroepen; Mustafa Kemal Pasja werd tot eerste president gekozen. Het 624 jaar durende Osmaanse avontuur, dat in 1299 als grensbeylik was begonnen, was zo gesloten en de nieuwe staat, waarin de soevereiniteit onvoorwaardelijk aan de natie toebehoort, was gebouwd op de erfenis van het rijk.", "f5cabb8c"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Slaan van de eerste Osmaanse akçe", "38d2d638"], "d": ["De eerste zilveren akçe, geslagen in naam van Orhan Gazi, is de monetaire proclamatie van de onafhankelijke soevereiniteit van het beylik; de akçe bleef vijf eeuwen lang de basismunteenheid.", "8729ab5b"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Eerste Osmaanse gouden munt (sultanî) geslagen", "2fd5c0dd"], "d": ["De eerste Osmaanse gouden munt, gelijk aan de Venetiaanse dukaat, werd geslagen; de rijksfinanciën sloten zich aan bij de internationale monetaire orde.", "cac00614"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Eerste uitgebreide capitulaties met Frankrijk", "e2264e48"], "d": ["Als onderdeel van het Franse bondgenootschap tegen de Habsburgse omsingeling werden handelsprivileges ondertekend tussen Jean de la Forest en Makbul İbrâhim Pasja; de capitulaties, die toen een diplomatiek instrument waren, zouden in de loop van de eeuwen de deur naar financiële afhankelijkheid worden.", "e7c6fd84"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Grote muntverslechtering — akçe-crisis", "9205c3d4"], "d": ["Onder druk van de lange oorlogen en het Amerikaanse zilver werd het zilvergehalte van de akçe gehalveerd; de prijsrevolutie voedde het uiteenvallen van het sipahi-stelsel en de Celali-onrust.", "bd2a508f"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Inname van Köprühisar en voorbereiding op de stichting van Yenişehir", "39abff03"], "d": ["Door de passenvestingen tussen Bursa en İznik te laten vallen, werd de basis gelegd voor het voorste hoofdkwartier dat beide steden in een omsingeling zou nemen.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Stichting van Yenişehir", "d3275837"], "d": ["Om de belegeringen van Bursa en İznik te leiden werd de eerste reguliere Osmaanse garnizoensnederzetting gesticht; Orhan Gazi werd hier geboren.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Eerste beleg van İznik en verovering van Marmaracık", "cdca2349"], "d": ["İznik werd voor het eerst belegerd maar kon niet worden ingenomen (definitieve verovering 1331); de nabijgelegen burcht Marmaracık werd in die tijd ingenomen.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Veldtocht van de Catalaanse troepen in Anatolië", "4fd940d5"], "d": ["De Catalaanse compagnie, door Byzantium ingehuurd om de Turkse opmars te stoppen, behaalde tijdelijke successen maar bleef niet; met hun terugtrekking versnelde de opmars van de grensbeyliks.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal wordt moslim en sluit zich aan bij de Osmanen", "ca0d86e1"], "d": ["De tekfur van Harmankaya, Köse Mihal, werd met zijn burcht en manschappen moslim en sloot zich aan bij Osman Gazi; hij werd de eerste Byzantijnse Osmaanse commandant.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey neemt het feitelijke bestuur over", "6dadbefc"], "d": ["Vanwege de ouderdom en ziekte van Osman Gazi ging de feitelijke leiding en het bevel over het beleg van Bursa en de veldtochten over op zijn zoon Orhan Bey (de formele troonsbestijging is in 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Inname van Mudanya", "0a623368"], "d": ["Met de inname van Mudanya, de haven van Bursa, werd de zeeverbinding van de stad afgesneden; het beleg van Bursa ging de fase van wurging in.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Verovering van Akyazı en het eiland İmralı", "d041b0c8"], "d": ["Akyazı ten noorden van de Sakarya werd ingenomen; met de inname van het eiland İmralı kwamen de Osmanen voor het eerst in de buurt van het eiland Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Verovering van Gemlik (Kios) en Armutlu", "682d3bac"], "d": ["Ook de laatste zeeverbinding van Bursa werd afgesneden en de stad werd rijp gemaakt voor de overgave in 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca veroverde Kandıra en omgeving", "341bb97e"], "d": ["Akça Koca, een van de grensbeys van Orhan Gazi, nam rond 1326 Kandıra en omgeving in terwijl hij vanuit zijn hoofdkwartier ten westen van het Sapanca-meer strooptochten naar de streek van İzmit ondernam. İzmit was nog in Byzantijnse handen; de stad zou pas in 1337 vallen.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Aansluiting van Yalova en Karamürsel", "133cb07a"], "d": ["Yalova en omgeving aan de zuidkust van de baai van İzmit kwamen dit jaar in Turkse handen; de kuststrook werd door Orhan Bey als timar aan Karamürsel Gazi gegeven.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca nam Aydos en de vesting Samandıra in", "ce4daa8a"], "d": ["Na de inname van Kandıra nam Akça Koca samen met Konuralp en Gazi Abdurrahman de burcht Aydos bij Kartal en daarna de vesting Samandıra ten noorden daarvan in; het gebied Samandıra werd hem als eigendom gegeven. Akça Koca stierf in 1328 bij Kandıra; het grensbeylik werd aan prins Murad gegeven.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Osmaans-Aydın-Saruhan-bondgenootschap", "9df6bb74"], "d": ["De drie beyliks traden gezamenlijk op tegen Byzantium; de vloot van Umur Bey van de Aydınoğulları sleet Byzantium op een tweede front af met overvallen op de kust van Thracië.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Huwelijk van Orhan Gazi en Theodora: Byzantijns bondgenootschap", "9b67a590"], "d": ["Orhan Gazi, die in de Byzantijnse troonstrijd Kantakouzenos steunde, trouwde met diens dochter Theodora; dit bondgenootschap stelde de Osmaanse strijdkrachten in staat Rumelië van dichtbij te leren kennen.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Inname van Ankara", "49bf1f6d"], "d": ["Ankara, onder bestuur van de ahi's, kwam onder Osmaans bestuur; de weg naar Midden-Anatolië werd geopend. Andere plaatsen die op dezelfde datum werden toegevoegd: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Opmars in Thracië onder Süleyman Pasja: Malkara, İpsala en Tekirdağ", "fb31cf02"], "d": ["Nadat het bruggenhoofd bij Gallipoli was gevestigd, trok Süleyman Pasja vanaf het schiereiland naar het noorden en veroverde stap voor stap de vlakte tussen de kust van de Zee van Marmara en de monding van de Maritsa. Malkara, İpsala en Rodosçuk (Tekirdağ) vormden zo een ononderbroken corridor die Gallipoli met de Maritsavallei verbond. Zonder deze corridor kon men niet op Edirne oprukken; de opmars, die tot stilstand kwam door de plotselinge dood van de prins in 1357, zou door Lala Şahin en Hacı İlbey worden voortgezet.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Ontvoering van prins Halil", "b52ac3d7"], "d": ["Halil, de jongere zoon van Orhan Gazi, werd door piraten uit Foça ontvoerd; de losgeldcrisis hield de Osmaans-Byzantijnse betrekkingen jarenlang bezig.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Afsnijden van de hulproutes van Edirne: de burchten Çorlu, Lüleburgaz, Babaeski en Keşan", "8e8ad485"], "d": ["Prins Murad, die na de bevrijding van Halil de veroveringscampagne hervatte, stuurde ruiters tot voor Constantinopel om Edirne af te snijden van hulp van buiten. De burchten Çorlu, Lüleburgaz en Babaeski aan de weg Constantinopel–Edirne en Keşan aan het wegkruispunt van Zuid-Thracië werden ingenomen. De overgave van Edirne kwam nadat deze belegeringsring was voltooid.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Inname van Dimetoka — opening van de Maritsavallei", "b59aee83"], "d": ["Dimetoka (Didymoteicho), de sleutelburcht van de Maritsavallei, werd ingenomen; zo werd de weg naar de verovering van Edirne geopend. Zonder de voltooiing van de corridor die zich van Gallipoli naar het noorden uitstrekt was het niet mogelijk op Edirne op te rukken, daarom komt de burcht in de volgorde van de Rumeliaanse veroveringen vóór Edirne. De stad werd een tijd lang het Rumeliaanse hoofdkwartier van de sultans. De strijdkrachten die Dimetoka innamen, brachten daarna samen met kleine burchten zoals Kuleli Burgaz (Pythion) het hele gebied van de Midden-Maritsa onder controle.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Verlies van Gallipoli (Savoyaardse kruistocht)", "00e7e415"], "d": ["De vloot van Amadeus van Savoye, neef van de Byzantijnse keizer, nam Gallipoli in en droeg het over aan Byzantium; het Osmaanse bruggenhoofd in Rumelië werd tien jaar lang vanaf de overkant van de zeestraat bestuurd. Andere plaatsen die op dezelfde datum verloren gingen: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Slag bij Çirmen — controle over de Maritsavallei", "cd738d8d"], "d": ["Het leger van de Servische beys werd bij een nachtelijke overval uiteengeslagen; de Servische/Bulgaarse lokale beys in Macedonië en de Rodopen begonnen een voor een schatting aan de Osmanen te betalen — geen directe verovering, maar het begin van een golf van vazalisering. In de Osmaanse overlevering wordt deze slag bovendien verteld onder de naam 'Sırpsındığı' en in het jaar 1364, als de nachtelijke overval van Hacı İlbey op het kruisvaardersleger dat kwam om Edirne terug te nemen; de TDV vermeldt dat die datum onjuist is en dat de twee verhalen op dezelfde slag betrekking hebben.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Verovering van Filibe en Eski Zağra", "e780c9ae"], "d": ["Filibe (Plovdiv) hoger in de Maritsavallei en Eski Zağra (Stara Zagora) ten noorden ervan werden ingenomen; het Bulgaarse tsarenrijk werd schatplichtig gemaakt. De route Tatarpazarcığı–İhtiman tussen Filibe en Sofia bleef in handen van de lokale beys die na Çirmen vazallen waren geworden.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Vazal Byzantium: Johannes V in het leger van Murad I (gevolg van de overwinning bij Çirmen in 1371)", "13ffe568"], "d": ["Volgens de TDV had het Byzantijnse Rijk na de overwinning bij Çirmen (Maritsa) op 26 september 1371 de Osmaanse heerschappij erkend en was het in de positie van vazalstaat gekomen door schatting te betalen en dienst in het Osmaanse leger te aanvaarden. Keizer Johannes V sloot zich met deze verplichting in 1373 aan bij het leger van Murad I; zijn zoon Andronikos IV, die hij toen in Constantinopel had achtergelaten, kwam samen met prins Savcı Bey in Bursa in opstand tegen hun vaders.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Herovering van Gallipoli", "5f96c0a5"], "d": ["Andronikos IV, die in de Byzantijnse troonstrijd Osmaanse steun kreeg, gaf als tegenprestatie Gallipoli terug; de brug tussen Rumelië en Anatolië was opnieuw gevestigd. Andere plaatsen die op dezelfde datum werden toegevoegd: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Germiyan-bruidsschat: aansluiting van Kütahya", "d6a6fe61"], "d": ["Bij het huwelijk van Devletşah Hatun, de dochter van Germiyanoğlu Süleyman Şah, met Yıldırım Bayezid gingen Kütahya, Simav, Tavşanlı en Eğrigöz als bruidsschat naar de Osmanen — het klassieke voorbeeld van expansie zonder oorlog. Andere plaatsen die op dezelfde datum werden toegevoegd: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Aankoop van het gebied Hamid: aansluiting van Isparta", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bey verkocht een deel van zijn beylik (Akşehir-Beyşehir-Isparta) tegen contante betaling aan Murad I; de rest van het gebied Hamid zou in 1391 door Yıldırım worden geannexeerd.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Verovering van Serres", "d4d28b60"], "d": ["Serres, de sleutel van Oost-Macedonië, werd ingenomen; Thessaloniki kwam binnen de belegeringsring. De lijn Köstendil–Petriç–Nevrokop–Drama tussen Sofia en Serres was op deze datum nog niet rechtstreeks toegevoegd; zij werd in de jaren 1370–1383 vazal en na 1383 rechtstreeks bestuurd.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Verovering van Sofia", "96d5f01f"], "d": ["De westelijke passen van het Balkangebergte kwamen onder controle; omdat Serres op deze datum al sinds 1383 in handen was, vormden de gebieden Thracië en Macedonië een ononderbroken geheel.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Verovering van Niš", "77f5d632"], "d": ["Met de inname van Niš, het slot van de Moravavallei, kwam het Servische despotaat direct onder dreiging.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Eerste overgave van Thessaloniki", "96010ee9"], "d": ["Na een lange blokkade gaf de stad zich over (zij zou in 1403 aan Byzantium worden teruggegeven en in 1430 definitief worden veroverd). Andere plaatsen die op dezelfde datum werden toegevoegd: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Osmaans-Genuees ahidname — vernieuwing van het verdrag van 1352", "be11d17a"], "d": ["Met de Genuese gezanten uit Pera werd het handelsverdrag van 1352 uit de tijd van Orhan Gazi vernieuwd; de belastingen tussen beide staten, de behandeling van krijgsgevangenen en de vrije handel werden opnieuw vastgelegd. Dit wordt beschouwd als de eerste officieel bekende ahidname van vriendschap en handel tussen de Osmanen en de Genuezen — geen militair bondgenootschap, maar een zuiver commerciële overeenkomst.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Veldtocht van Çandarlı Ali Pasja in Bulgarije: inname van Şumnu en Rusçuk", "2781c3a9"], "d": ["De burchten van het Bulgaarse tsarenrijk langs de Donau werden in één veldtocht overgenomen; niet te verwarren met de nederlaag die in hetzelfde jaar bij Bileća in Bosnië werd geleden — dit was een gelijktijdig succes aan een apart front. Tırnova en Vidin waren de laatste Bulgaarse centra die nog in handen werden gehouden.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Nederlaag bij Bileća", "89ba0a64"], "d": ["De ruitermacht die naar Bosnië optrok, werd bij Bileća in een hinderlaag gelokt en vernietigd; deze eerste grote tegenslag op de Balkan moedigde het bondgenootschap aan dat naar Kosovo leidde.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Annexatie van de West-Anatolische beyliks: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Drie beyliks werden in één keer toegevoegd: Manisa, centrum van de Saruhanoğulları; Aydın, centrum van de Aydınoğulları (inclusief de Bovenburcht van Smyrna, maar de haven/benedenburcht bleef tot 1402 bij de Sint-Jansridders); Muğla-Milas, centrum van de Menteşeoğulları, inclusief de kuststrook Datça-Bodrum-Marmaris-Fethiye. De Egeïsche kusten werden voor het eerst in één hand verenigd. Andere plaatsen die op dezelfde datum werden toegevoegd: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Annexatie van het gebied Teke: aansluiting van Antalya", "fdbeee5c"], "d": ["Het gebied Teke aan de Middellandse Zeekust werd bij het Osmaanse grondgebied gevoegd. De Tekeoğulları zijn een afsplitsing van de Hamîdoğulları: Feleküddin Dündar Bey liet het door hem veroverde Antalya aan zijn broer Yûnus Bey, waarna omstreeks 1321 een afzonderlijk beylik ontstond. Daarom worden Antalya en omgeving na 1321 op de kaart niet in de kleur van de Hamîdoğulları maar in die van de Tekeoğulları weergegeven. Het beylik werd na de Slag bij Ankara opnieuw gesticht en pas in 1423 definitief geliquideerd.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Verovering van Üsküp (Skopje)", "9e5a1af5"], "d": ["Het centrum van Vardar-Macedonië werd ingenomen; Üsküp werd een van de voornaamste grenscentra van Rumelië.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Annexatie van Kastamonu", "876330ba"], "d": ["De Kastamonu-tak van de Candaroğulları werd geliquideerd; de Sinop-tak bleef als vazal voortbestaan. Andere plaatsen die op dezelfde datum werden toegevoegd: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Val van Tırnova — annexatie van Bulgarije", "ff666977"], "d": ["De hoofdstad van het Bulgaarse tsarenrijk viel; Bulgarije kwam rechtstreeks onder Osmaans bestuur. Andere plaatsen die op dezelfde datum werden toegevoegd: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Burcht Lofça (Loveč) kwam in Osmaanse handen", "a55e87a0"], "d": ["Lofça, een van de burchten van de Bulgaarse tsaar Ivan Šišman, werd tijdens de veldtocht van 1393, waarin Tırnova viel, samen met de overige provincies van Šišman bij het Osmaanse grondgebied gevoegd. De bron is niet stellig: 'er wordt aangenomen' dat de verovering dit jaar plaatsvond.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Aansluiting van Dobroedzja", "478e36f2"], "d": ["De gebieden van Dobroedzja die zich uitstrekken tot de Donaudelta werden toegevoegd. Andere plaatsen die op dezelfde datum werden toegevoegd: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Afdaling naar Thessalië", "8bec60dd"], "d": ["De vlakte van Thessalië met als centrum Yenişehir (Larissa) werd onder Osmaans bestuur gebracht. Andere plaatsen die op dezelfde datum werden toegevoegd: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1394-01-01:1":{"b": ["Strak beleg van Constantinopel begon (blokkade sinds ~1387)", "0068bc04"], "d": ["Yıldırım Bayezid hield Constantinopel met tussenpozen tien jaar lang geblokkeerd; de stad werd pas gered doordat Timur naderde.", "504fcb33"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Slag bij Rovine — veldtocht naar Walachije", "343ae7a9"], "d": ["Na de bloedige slag met de Walachijse woiwode Mircea, waarvan de uitkomst omstreden is, aanvaardde Walachije schatting te betalen aan de Osmanen; de vazalorde ten noorden van de Donau werd gevestigd.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Verovering van Nikopol", "b9791717"], "d": ["Na de slag bij Rovine in 1395 tegen de Walachen nam Yıldırım Bayezid de burcht Nikopol aan de Donau in; sommige anonieme Bulgaarse kronieken geven aan dat de verovering op 3 juni 1395 plaatsvond. De veroveringsdatum is in de bronnen niet eenduidig: het lemma Niğbolu Savaşı in de TDV İslâm Ansiklopedisi schrijft dat Bayezid Silistra en Nikopol in een Donaucampagne in 1394 innam. De burcht zou tijdens de beroemde kruistocht van 1396 worden belegerd, maar niet vallen. Andere plaatsen die op dezelfde datum werden toegevoegd: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Burcht Nikopol kwam aan de Osmanen", "327012c9"], "d": ["Na de overval bij Rovine nam Yıldırım Bayezid Nikopol in; de Bulgaarse tsaar Ivan Šišman, die daar als Osmaanse vazal woonde, werd uitgeschakeld. In de atlas staat Nikopol vanaf deze dag geschreven van het Bulgaarse tsarenrijk naar de Osmanen.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Bouw van Anadolu Hisarı", "aa259b00"], "d": ["Om de blokkade van Constantinopel te ondersteunen werd aan de Anatolische kant van de Bosporus Güzelcehisar (Anadolu Hisarı) gebouwd — de eerste blijvende stap in de controle van de zeestraat.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Annexatie van Vidin", "ee1ae44b"], "d": ["Na de overwinning bij Nikopol werd ook het laatste Bulgaarse vorstendom Vidin geannexeerd.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Eerste annexatie van Karaman", "3cf07876"], "d": ["Met de overwinning bij Akçay werd het gebied van de Karamanoğulları voor het eerst bij de Osmanen gevoegd (het zou tijdens het Interregnum opnieuw worden gevestigd).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Aansluiting van de Canik-kusten: Samsun", "af9c40fa"], "d": ["In het vacuüm dat ontstond doordat Kadı Burhâneddin in handen viel van Karayülük Osman Bey van de Akkoyunlu, bracht Yıldırım Bayezid eerst het Canik-gebied aan de Zwarte Zeekust onder Osmaans bestuur. Samsun en omgeving werden zo de eerste Zwarte Zeehaven van de dynastie. De lijn Sivas–Tokat–Kayseri in het binnenland zou twee weken later worden toegevoegd met het feitelijke uiteenvallen van de staat van Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Inname van Malatya", "7cb6ae16"], "d": ["Malatya aan de Mamelukse grens werd ingenomen — een van de stappen die de spanning met Timur deden toenemen.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur nam Malatya in en liet het aan Karayülük Osman — toen Timur zich terugtrok, namen de Dulkadıroğulları het terug", "ad2ce7d8"], "d": ["Yıldırım Bayezid had Malatya, dat hij in 1399 had ingenomen, aan Dulkadıroğlu Nasreddin Mehmed overgelaten en was naar Bursa teruggekeerd. Timur, die in 1400 Anatolië binnentrok, nam eerst Sivas en Elbistan in en daarna Malatya; de stad en omgeving werden geplunderd en het bestuur werd overgelaten aan Karayülük Osman, die zich bij Timur bevond. Toen Timur de regio verliet, kwam Malatya opnieuw onder de heerschappij van de Dulkadıroğulları; de Osmaanse heerschappij eindigde zo vóór Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Süleyman Çelebi – Byzantijns verdrag: teruggave van Thessaloniki", "cc503cc2"], "d": ["Süleyman Çelebi, die tijdens het Interregnum over Rumelië heerste, liet in overeenstemming met de Byzantijnse en Latijnse staten Thessaloniki en de Zwarte Zeekust tot Mesembria aan Byzantium (TDV fetret-devri: Verdrag van Gallipoli, februari 1403) — op de kaart gaan İğneada, Rezve en Ahtapolu naar Byzantium; Thessaloniki verlaat op deze datum het Osmaanse bezit.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Zeenederlaag bij Gallipoli (Venetië)", "b71d4d68"], "d": ["De Venetiaanse vloot bracht de Osmaanse vloot voor Gallipoli een zware nederlaag toe; een gebeurtenis die de grenzen van de vroege Osmaanse zeevaart toonde.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Opstand van Düzmece Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, die beweerde een zoon van Yıldırım te zijn, riep met Byzantijnse steun in Rumelië het sultanaat uit; Murad II sloeg de opstand in 1422 neer en liet zijn rivaal executeren.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Beleg van Constantinopel door Murad II", "4b9d9fba"], "d": ["Als antwoord op de Byzantijnse steun voor Düzmece Mustafa belegerde Murad II Constantinopel; het beleg werd opgeheven nadat zijn broer Küçük Mustafa in Anatolië in opstand was gebracht.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Overdracht van Thessaloniki aan Venetië", "bfa6c4a0"], "d": ["De Byzantijnse gouverneur droeg de stad onder Osmaanse druk over aan Venetië; de zeven jaar durende Osmaans-Venetiaanse strijd begon.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Heroverde annexatie van de West-Anatolische beyliks: Menteşe en Aydın", "aca30a48"], "d": ["De twee Egeïsche beyliks die tijdens het Interregnum opnieuw waren gesticht, werden onder Murad II definitief bij het Osmaanse grondgebied gevoegd. Volgens het TDV-lemma Menteşeoğulları nam Murad II het gebied Menteşe in 827 (1424) in en liet hij de twee broers aan het hoofd van het beylik gevangenzetten. Volgens het lemma Aydınoğulları liet de beylerbey van Anatolië, Hamza Bey, Cüneyd Bey, die opnieuw ongehoorzaam was geworden, grijpen en samen met zijn familie executeren (829/1425-26) en kwam het gebied Aydın aan de Osmanen. De Sint-Jansridders, die de havenburcht van Smyrna sinds 1344 in handen hielden, hadden deze in 1402 aan Timur verloren en de regio was weer onder controle van de Aydınoğulları gekomen; met deze annexatie werd ook deze bij de Osmanen gevoegd. Het gebied Teke (Antalya) is geen onderwerp van dit item: de Tekeoğulları waren in 1423 afzonderlijk geliquideerd. Germiyan zou in 1429 bij testament worden toegevoegd.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Annexatie van Germiyan bij testament", "9eb86b77"], "d": ["Germiyan-bey Yakub II, die kinderloos stierf, liet zijn land bij testament aan de Osmanen na — het schoolvoorbeeld van annexatie zonder oorlog. Andere plaatsen die op dezelfde datum werden toegevoegd: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Definitieve verovering van Thessaloniki", "bc021768"], "d": ["De door Venetië bestuurde stad werd bij storm ingenomen; de tweede grote haven van Rumelië werd definitief Osmaans. Andere plaatsen die op dezelfde datum werden toegevoegd: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Overgave van Ioannina", "ee45cb52"], "d": ["Ioannina, het centrum van Epirus, gaf zich bij verdrag over.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Eerste inname van Smederevo", "c11ca17d"], "d": ["Met een beleg van drie maanden werd de hoofdstad van het Servische despotaat ingenomen en Servië voor het eerst geannexeerd (het zou met het Verdrag van Edirne-Szeged in 1444 worden teruggegeven).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Beleg van Belgrado (mislukt)", "3e05f425"], "d": ["Het eerste grote beleg van Belgrado, dat zes maanden duurde, bracht niets op; de burcht bleef tachtig jaar lang een slot voor de Osmaanse opmars.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Nederlaag bij Zlatitsa — de 'Lange Veldtocht'", "97df1466"], "d": ["Het leger dat Hunyadi midden in de winter de Balkan binnenvoerde, trok voorbij Niš en Sofia en kwam tot Zlatitsa; de Osmaanse verdediging hield met moeite stand. Deze sfeer van nederlaag bracht de vrede van Edirne-Szeged aan de onderhandelingstafel.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Verdrag van Edirne-Szeged", "0aa4e0de"], "d": ["Tienjarige vrede: het Servische despotaat werd teruggegeven, de Donau werd als grens aanvaard. Dat het verdrag binnen enkele maanden door pauselijke aanstoken werd verbroken, leidde tot de ramp bij Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Teruggave van Smederevo en de Servische burchten aan Servië", "cda3cf9e"], "d": ["De bepaling van het Verdrag van Edirne-Szeged werd uitgevoerd: Murad II gaf op 15 augustus 1444 Smederevo met zijn vierentwintig belangrijke burchten en de overige bezette Servische gebieden terug aan Đurađ Branković (TDV semendire); ook Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) en Priština (TDV pristine) werden aan de Serviërs gelaten. Vidin was geen Servisch gebied en kwam dus niet in aanmerking voor teruggave — dit is de bron van het noordwestelijke gebiedsverlies dat op de kaart rond de overwinning bij Varna te zien is; enkele maanden later zou het verdrag met de nederlaag bij Varna toch ongeldig worden.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Rumeli Hisarı voltooid — 'Boğazkesen' (Zeestraatdoorsnijder)", "480e8a76"], "d": ["Met de burcht, volgens de bronnen in buitengewoon snel tempo in vier à vijf maanden voltooid, ging de controle over de Bosporus volledig naar de Osmanen; de hulproute vanaf de Zwarte Zee naar Constantinopel werd afgesloten. Zij geldt als de feitelijke eerste stap van het beleg.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Beleg van Constantinopel begon", "8af50742"], "d": ["Het leger nam positie voor de muren; in het 54 dagen durende beleg werden reusachtige kanonnen voor het eerst systematisch tegen de muren van een hoofdstad ingezet.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Schepen over land naar de Gouden Hoorn gebracht", "4f2ba07c"], "d": ["Ongeveer 70 schepen van de vloot, die de met een ketting afgesloten Gouden Hoorn niet in kon, werden met gesmeerde sleden over de heuvels van Galata gesleept en in één nacht in de Gouden Hoorn gelaten; de verdediging werd in twee fronten gesplitst.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Verovering van Athene", "4f0f1bb2"], "d": ["Het Hertogdom Athene kwam ten einde; de Osmaanse vlag werd op de Akropolis gehesen. Andere plaatsen die op dezelfde datum werden toegevoegd: İstefe (Thebe), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Annexatie van Servië (val van Smederevo)", "75fd0a62"], "d": ["Smederevo, de hoofdstad van het Servische despotaat, gaf zich over; Servië werd een Osmaanse sandjak.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Verovering van de Morea", "7d5a3c18"], "d": ["Het despotaat Morea werd geliquideerd; het schiereiland (met uitzondering van de Venetiaanse burchten) kwam onder Osmaans bestuur.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Aansluiting van Sinop", "e03c2739"], "d": ["Candaroğlu gaf Sinop zonder strijd over; de weg naar de veldtocht tegen Trebizonde lag open. Andere plaatsen die op dezelfde datum werden toegevoegd: Kastamonu, Bartın, Safranbolu. Het TDV-lemma Candaroğulları noemt ook Bolu, Eflani en Tosya onder de gebieden van het Candaroğlu-beylik die in 1461 werden geannexeerd; in de atlas staan ook deze drie plaatsen op deze dag geschreven van Candaroğlu naar de Osmanen.", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Ondergang van het Koninkrijk Bosnië — Bosnische veldtocht van de Veroveraar", "5362e3f2"], "d": ["Toen de laatste Bosnische koning Stjepan Tomašević (1461-1463), vertrouwend op westerse steun, weigerde schatting te betalen, werd hij geacht geen vazalheerser meer te zijn en liquideerde het leger onder Mehmed de Veroveraar het Koninkrijk Bosnië in één veldtocht. De koning werd gevangengenomen en geëxecuteerd, het koninkrijk verdween en in de regio werd de sandjak Bosnië gesticht. De ondergang van het koninkrijk is echter niet hetzelfde als de verovering van Bosnië. Het Osmaanse bestuur was in de vlakte al vijftien jaar aanwezig — Hodidjed en de vlakte van Saray waren in 1448 ingenomen, het grensbeylik van Îsâ Bey was midden in het koninkrijk gesticht. De verovering was ook in 1463 niet klaar: Foča werd in 1465 ingenomen, Livno in 1469, het Hertogdom Herzegovina in 1483, het banaat Srebrenik in 1512, en Jajce en Banja Luka in het noorden pas in 1528 na Mohács — de Hongaren hadden na 1463 in het noorden van Bosnië een banaat gevestigd dat vijfenzestig jaar standhield. De plaats die op deze datum rechtstreeks van hand wisselde is Travnik; Jajce ging op deze datum niet naar de Osmanen maar naar Hongarije.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Definitieve annexatie van Karaman", "f1dcecaa"], "d": ["De kerngebieden van de Karamanoğulları werden definitief toegevoegd; de interne twisten duurden tot de jaren 1470 voort. Andere plaatsen die op dezelfde datum werden toegevoegd: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Verovering van Negroponte (Euboea)", "5c97daf3"], "d": ["Negroponte, de belangrijkste Venetiaanse basis in de Egeïsche Zee, viel.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Annexatie van Alanya, Anamur en Silifke (İçel)", "a0b9d461"], "d": ["De kuststrook İçel die aan de Karamanoğulları toebehoorde (de gehele Middellandse Zeekust tussen Antalya en Mersin) werd toegevoegd door de zeecampagne van Gedik Ahmed Pasja; Alanya was belangrijk vanwege zijn strategische scheepswerf uit de Seltsjoekse tijd.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Annexatie van Novgorod door Moskou", "bed87170"], "d": ["Grootvorst Ivan III liet de symbolische klok van de volksvergadering (veche) in Novgorod weghalen, verving de lokale bestuurders door zijn eigen gouverneurs en bond de stad feitelijk aan Moskou; Novgorod hield op een onafhankelijke republiek te zijn. Het grondgebied van Novgorod strekte zich uit van de Oostzee tot de Witte Zee en de Oeral. In de atlas staat Novgorod vanaf deze dag geschreven van de Republiek Novgorod naar Moskou.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Verdrag van Constantinopel — Albanië en Shkodër", "b09652f7"], "d": ["De 16 jaar durende Osmaans-Venetiaanse oorlog eindigde; Shkodër en de Albanese kusten bleven Osmaans. Andere plaatsen die op dezelfde datum werden toegevoegd: Limni, Sisam, Bozbaba (Agios Efstratios).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Landing bij Otranto", "7916b89d"], "d": ["De Osmaanse strijdkrachten die op de kust van Apulië (Pulya) landden, belegerden en namen de burcht Otranto in; omdat de stad met geweld werd binnengegaan, werd een deel van de verzetsleiders geëxecuteerd en een deel gevangengenomen. De kerkelijke traditie herdenkt de doden als de 'martelaren van Otranto', ongeveer 800 personen; de TDV schrijft de overdrijving van dit aantal toe aan kerkelijke propaganda. Alleen de burcht aan de punt van het schiereiland Salento en zijn smalle omgeving werd gehouden; de overige gebieden van het Koninkrijk Napels op de lijn Taranto–Brindisi–Lecce gingen niet verloren — dit bruggenhoofd naar Italië zou een jaar duren.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Ontruiming van Otranto", "37371bb0"], "d": ["Na de dood van Mehmed de Veroveraar (3 mei 1481) ontruimde het garnizoen van Otranto, dat geen hoop op nieuwe versterkingen meer had, de burcht bij overeenkomst tegenover het beleg van de Napolitaanse kroonprins Alfonso; het enige Osmaanse bruggenhoofd in Italië ging zo een jaar later verloren.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Verovering van Modon en Koron", "38b608c4"], "d": ["Modon en Koron, de 'twee ogen' van Venetië in de Morea, werden ingenomen.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Verovering van Durrës", "1f231b98"], "d": ["Tijdens de Osmaans-Venetiaanse oorlog van 1499-1503 namen de strijdkrachten onder bevel van Mehmed Bey Durrës in, de laatste grote Albanese haven van Venetië aan de Adriatische Zee. Na Shkodër (1479) en Vlorë (1417) kwam met deze verovering de gehele Albanese kuststrook onder Osmaanse controle.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Aansluiting van Oost-Anatolië", "e0cb8f8f"], "d": ["Na Çaldıran werden Diyarbakır en omgeving toegevoegd; de Koerdische beyliks werden door toedoen van İdrîs-i Bitlisî aan de Osmanen gebonden.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Verovering van de burcht Varadin (Petrovaradin)", "abf392a5"], "d": ["Het leger dat voor de veldtocht naar Mohács uittrok, stak vanuit Belgrado over naar Hongaars grondgebied; eerst werden de buitenwijken van Varadin ingenomen en na een beleg van veertien dagen viel ook de burcht. Süleyman beval de dorpen onderweg niet in brand te steken omdat deze voortaan als Osmaans grondgebied golden.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Overgave van Boeda na Mohács — twee koningen op de Hongaarse troon", "9d3568a0"], "d": ["Nadat het Osmaanse leger na de overwinning bij Mohács naar Boeda was opgerukt, werden de sleutels van de stad op 11 september 1526 aan de sultan aangeboden; maar Süleyman hield Boeda niet en trok zijn leger terug. In het koningloze Hongarije kozen de edelen twee afzonderlijke koningen: op 10 november 1526 János Szapolyai, op 17 december 1526 de Habsburger Ferdinand I. Ferdinand nam Boeda in augustus 1527 in. De vestiging van Szapolyai in Boeda als koning onder Osmaanse bescherming zou plaatsvinden met de veldtocht van 1529 (zie het item van 1529), het rechtstreekse Osmaanse bestuur zou in 1541 worden gevestigd.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai tot Hongaars koning gekozen — de Osmanen erkenden zijn koninkrijk op voorwaarde van vazalschap", "32bc6baf"], "d": ["Een deel van de adel koos de woiwode van Transsylvanië János Szapolyai tot de Hongaarse troon die na de dood van de koning bij Mohács vacant was geworden; Szapolyai werd in Székesfehérvár gekroond. De Osmanen, die Boeda hadden verlaten, erkenden het koninkrijk van Szapolyai op voorwaarde dat het hun vazal was om het gebied als bufferzone te houden. Op de kaart staan de plaatsen die van Szapolyai afhangen vanaf deze datum als Osmaans vazalgebied.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand I tot Hongaars koning uitgeroepen — West- en Noord-Hongarije naar de Habsburgse kroon", "b3910a2f"], "d": ["De Habsburgse aartshertog Ferdinand maakte, steunend op het huwelijk van zijn zuster met Lodewijk II, aanspraak op de Hongaarse troon en werd door een deel van de edelen tot koning uitgeroepen. Hongarije werd zo verdeeld tussen twee koningen; het westelijke en noordelijke deel erkende Ferdinand. De Kroatische edelen kozen hem begin 1527 afzonderlijk.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Strijd tussen de twee koningen: Esztergom onder Habsburgse bescherming, Szeged bij Szapolyai", "da92dee5"], "d": ["Esztergom, dat sinds 1526 tussen de twee koningen van hand wisselde, kwam onder Habsburgse bescherming nadat de aartsbisschop met zijn archief en schatkist naar het noorden was vertrokken. Vanaf datzelfde jaar tot 1541 bleef Szeged onder de heerschappij van Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Inwoners van Pécs kozen de kant van Szapolyai", "3fc4e7f2"], "d": ["Pécs, dat in 1528 privileges van Ferdinand had ontvangen, koos kort daarna de kant van Szapolyai; koning János verbleef in 1533 enige tijd in de stad. Met de val van Boeda in 1541 keerde de stad weer terug naar de kant van Ferdinand.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Verovering van Tripoli", "8c659986"], "d": ["Tripoli werd van de Johannieters ingenomen; de middelste kust van Noord-Afrika werd Osmaans. Andere plaatsen die op dezelfde datum werden toegevoegd: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Verovering van Temesvár", "e9fd4995"], "d": ["Het gebied Banat werd ingenomen en het beylerbeylik Temesvár werd gesticht.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Definitieve verovering van Tunis", "7bbd11bc"], "d": ["Tunis, onder Spaans-Hafsidische controle, kwam definitief onder Osmaans bestuur; de Noord-Afrikaanse lijn was voltooid. Andere plaatsen die op dezelfde datum werden toegevoegd: Kairouan, Gabès, Sfax.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Verovering van Kanije", "0c7b6aa3"], "d": ["Kanije werd ingenomen in de Lange Oorlog; de verdediging van Tiryâki Hasan Pasja het jaar daarop werd legendarisch.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Veldtocht naar Uyvar begon — Fâzıl Ahmed Pasja trok vanuit Edirne tegen Oostenrijk op", "306a86db"], "d": ["Nadat Oostenrijk Transsylvanië had aangevallen en de burchten Székelyhíd en Kolozsvár had ingenomen, besloot Constantinopel tot een veldtocht tegen de Habsburgers. Grootvizier Köprülüzâde Fâzıl Ahmed Pasja vertrok op 13 april 1663 uit Edirne. In Belgrado kwam het Oostenrijkse verzoek om vrede, maar in twee gesprekken in Osijek werden de Osmaanse voorwaarden verworpen. Ook bij het overleg in Boeda werd Uyvar als doel vastgesteld.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Verovering van Uyvar", "ce289470"], "d": ["De sleutelburcht van Noord-Hongarije, Uyvar (Nové Zámky), werd ingenomen; de uitdrukking 'zo sterk als een Turk voor Uyvar' ging over in de Europese talen. Na Uyvar gaven ook Nitra en Léva zich na korte weerstand over; beide werden in de lente van 1664 door De Souches teruggenomen.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Herovering van de Morea", "9b6460f1"], "d": ["De Morea, die bij Karlowitz aan Venetië was gelaten, werd in één veldtocht teruggenomen. Andere plaatsen die op dezelfde datum werden toegevoegd: Balyabadra (Patras), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Tweede verlies van Belgrado — beleg door prins Eugenius", "6a194354"], "d": ["Na de nederlaag bij Petrovaradin en het verlies van Temesvár belegerde prins Eugenius Belgrado; toen ook het ontzettingsleger dat kwam om de stad te redden werd verslagen, gaf de burcht zich over. De stad, die na Karlowitz in 1690 was heroverd, ging zo opnieuw verloren en de Donauverdedigingslinie stortte in. Belgrado zou pas tweeëntwintig jaar later, met het Verdrag van Belgrado van 1739, kunnen worden teruggenomen. Andere plaatsen die op dezelfde datum verloren gingen: Smederevo. De atlas schrijft bovendien de streken Hisarcık (Grocka) en Yagodina (Jagodina) op deze dag aan de Habsburgers toe (gebiedsdag; een plaatsniveaudag staat niet in de bron, verklaarde benadering); Mehadia gaat met de datum 27 augustus 1717 naar de Habsburgers (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Val van Özi (Očakov)", "90a67a6c"], "d": ["Özi, de sleutelburcht ten noorden van de Zwarte Zee, viel na een bloedige bestorming in Russische handen; de bevolking van de stad werd over de kling gejaagd.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Verdrag van Boekarest — verlies van Bessarabië", "932da4d6"], "d": ["Met het verdrag dat de Russische oorlog van 1806-1812 beëindigde, werd het gebied ten oosten van de Proet (Bessarabië) aan Rusland gelaten. Andere plaatsen die op dezelfde datum verloren gingen: Akkirman, Kili, Hotin, Bender, İsmail. De atlas beschouwt bovendien Chișinău (Kişinev), Bălți, Cahul (Kahul) en Orhei binnen Bessarabië op dezelfde dag als van Moldavië (Osmaanse vazal) naar Rusland overgegaan. Ook Soroca ging op dezelfde dag naar Rusland.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Verdrag van Edirne", "b3a8fe4c"], "d": ["Aan het einde van de oorlog waarin het Russische leger Edirne binnentrok, ging de Donaudelta verloren; de autonomie/onafhankelijkheid van Griekenland werd feitelijk erkend. Andere plaatsen die op dezelfde datum verloren gingen: İbrail, Anapa, Ahıska. Hoewel het verdrag het grondgebied teruggaf, maakte het niet meteen een einde aan de bezetting: Walachije-Moldavië en Silistra bleven tot de oorlogsschadevergoeding was betaald als onderpand onder Russisch bestuur — daarom staan deze plaatsen ook na 1829 op de kaart als bezet.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Edict van autonomie voor Servië — erfelijk vorstendom en garnizoensvoorwaarde", "6a5d901d"], "d": ["Het hatt-ı hümâyun dat werd uitgevaardigd krachtens de bepaling van het Verdrag van Edirne over Servië erkende Miloš Obrenović als erfelijk vorst en maakte Servië tot een autonoom vorstendom, vrij in binnenlandse aangelegenheden en naar buiten toe aan de Osmanen gebonden. Bepalingen: het vorstendom gaat van vader op zoon over, de jaarlijkse belasting wordt als vast bedrag betaald, de Servische vergadering richt haar eigen binnenlands bestuur in, de kerk is autonoom; daartegenover bleven er Osmaanse garnizoenen in de burchten Belgrado, Smederevo, Šabac, Soko en Kladovo (Fethülislâm). Deze dubbele structuur duurde tot de terugtrekking van de garnizoenen in 1867. Op de kaart wordt de stad Belgrado op deze datum bij het autonome Servië gevoegd; de vesting Kalemegdan wordt tot 1867 als Osmaans garnizoen weergegeven.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Cyprus overgelaten aan Brits bestuur", "423da3ee"], "d": ["Het bestuur over Cyprus werd in ruil voor een bondgenootschap tegen de Russische dreiging aan Engeland overgedragen; juridisch bleef het Osmaans grondgebied. Andere plaatsen die op dezelfde datum verloren gingen: Nicosia, Famagusta, Kyrenia, Limassol, Larnaca (Tuzla), Paphos, Morphou (Güzelyurt), Akrotiri, Episkopi, Dhekelia; dat wil zeggen het hele eiland.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Thessalië aan Griekenland overgelaten", "ac614d24"], "d": ["Overeenkomstig de besluiten van het Congres van Berlijn werden Thessalië en de omgeving van Arta overgedragen aan Griekenland. Andere plaatsen die op dezelfde datum verloren gingen: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia). Met deze overdracht gingen ook Volos, Kalambaka en Karditsa (Thessalië) naar Griekenland.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Aansluiting van Oost-Roemelië bij Bulgarije", "ee43f137"], "d": ["De autonome provincie Oost-Roemelië werd met een staatsgreep bij Bulgarije gevoegd; de Hoge Porte aanvaardde voldongen feiten. Met deze eenwording ging heel Oost-Roemelië (Stara Zagora, Tatarpazarcığı, İslimye, Hasköy, Burgaz, Aydos, Elhova) over naar het Prinsdom Bulgarije.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Slag bij Domokos", "9c6f29a5"], "d": ["In de Osmaans-Griekse oorlog van 1897 behaalde het leger bij Domokos een beslissende overwinning; door diplomatieke druk bleef de gebiedswinst beperkt.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomie voor Kreta", "2e764881"], "d": ["Hoewel de Osmaans-Griekse oorlog met een Osmaanse overwinning eindigde, kondigden Engeland, Rusland, Frankrijk en Italië op 18 december 1897 de autonomie van Kreta af; het eiland zou onder Osmaanse heerschappij een neutrale en autonome provincie worden. Na 6 november 1898 werd in Candia en Kissamos de Turkse vlag niet meer gehesen; toen prins George, zoon van de Griekse koning, op 22 december 1898 als buitengewoon commissaris zijn ambt aanvaardde, verliet Kreta feitelijk het Osmaanse bestuur (formeel in 1913). Andere plaatsen die op dezelfde datum verloren gingen: Kandiye (Kreta), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Onafhankelijkheid van Bulgarije en annexatie van Bosnië", "393feaa4"], "d": ["In de verwarring van de constitutionele periode riep Bulgarije zijn onafhankelijkheid uit en annexeerde Oostenrijk-Hongarije Bosnië-Herzegovina. Met deze proclamatie werd het hele grondgebied van het Prinsdom Bulgarije (Varna, Şumnu, Rusçuk, Burgaz, İslimye enz.) het onafhankelijke Koninkrijk Bulgarije.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Herovering van Edirne", "536e5599"], "d": ["In de Tweede Balkanoorlog stak het leger de Maritsa over en nam Edirne zonder strijd terug. Andere plaatsen die op dezelfde datum werden toegevoegd: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Overwinning bij Kut al-Amara", "98b972bc"], "d": ["De commandant van de bij Kut ingesloten Britse divisie gaf zich met 13 duizend soldaten over — een van de grootste Osmaanse overwinningen van de Eerste Wereldoorlog.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Verlies van Bagdad", "2c18a816"], "d": ["Het 383 jaar Osmaanse Bagdad ging naar het Britse leger. Andere plaatsen die op dezelfde datum verloren gingen: Kerbela.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Verlies van Jeruzalem", "94067617"], "d": ["Het 401 jaar Osmaanse Jeruzalem werd zonder verdediging overgegeven.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Verlies van Damascus", "ed177b68"], "d": ["Met de ineenstorting van het Palestijnse front werd Damascus ontruimd; het vierhonderd jaar durende Osmaanse bestuur in Syrië kwam ten einde. Andere plaatsen die op dezelfde datum verloren gingen: Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Overgave van Medina", "76b505f6"], "d": ["Tweeënzeventig dagen na de wapenstilstand kwam het verzet van Fahreddin Pasja, de 'Woestijntijger', op bevel van de sultan ten einde; de laatste Osmaanse eenheid in de Hidjaz legde de wapens neer.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Bezetting van Smyrna", "e32e5e77"], "d": ["Het Griekse leger landde in Smyrna; het verzet dat met het eerste schot begon, ontstak de lont van de Nationale Strijd. Aydın werd op 27 mei 1919 bezet (afzonderlijk item).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Formele bezetting van Constantinopel", "a8e98ada"], "d": ["De Entente-troepen bezetten Constantinopel formeel en de Meclis-i Meb'ûsan werd ontbonden; de afgevaardigden trokken naar Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Verdrag van Kars", "bb32d4e0"], "d": ["Tussen de TBMM en de Kaukasische republieken werd de oostgrens getrokken zoals zij vandaag is.", "fe736259"]}
});
